{
  "narrative_summary": "Rebuild In House produced the best outcome in 58% of runs of this model, and Extend Vendor Contract produced the best outcome in 42% of runs. The link from Engineering Capacity to Total Cost of Ownership is not yet evidence-backed and could shift this.",
  "story_headlines": {
    "opt_rebuild": "Rebuild In House depends on engineering capacity holding up as modelled.",
    "opt_extend": "Extend Vendor Contract would need the vendor price path to stay favourable to produce the best outcome."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 61% of variations, based on current estimates.",
    "primary_risk": "The link from Engineering Capacity to Total Cost of Ownership is fragile and could flip which option this model points to.",
    "stability_factors": [],
    "fragility_factors": [
      "The link from Engineering Capacity to Total Cost of Ownership could flip the comparison if capacity assumptions change."
    ]
  },
  "readiness_rationale": "Two gaps still hold this back: engineering capacity is asserted rather than evidenced, and the vendor price path carries only moderate support. Firming these up would settle the comparison further.",
  "evidence_enhancements": {
    "fac_eng_capacity": {
      "specific_action": "Run a capacity audit with engineering leads to estimate realistic delivery timelines and staffing needs for an in-house build.",
      "rationale": "This factor is currently asserted rather than evidenced, and the comparison is sensitive to it.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the capacity figure before looking at the audit results."
    },
    "fac_vendor_price": {
      "specific_action": "Request a multi-year price schedule from the vendor, including any escalation clauses.",
      "rationale": "The cost path assumed for the vendor option is only moderately supported.",
      "evidence_type": "market_research",
      "decision_hygiene": "Write down your expected price trajectory before requesting the schedule."
    }
  },
  "scenario_contexts": {
    "edge_capacity_tco": {
      "trigger_description": "If Engineering Capacity turns out lower than assumed relative to Total Cost of Ownership...",
      "consequence": "...then this model points to Extend Vendor Contract rather than Rebuild In House."
    }
  },
  "flip_thresholds": [],
  "bias_findings": [
    {
      "type": "unsupported_link",
      "source": "structural",
      "description": "Engineering capacity is asserted rather than evidenced, yet the comparison is sensitive to it. Is that assumption tested enough to lean on?",
      "affected_elements": ["fac_eng_capacity", "edge_capacity_tco"],
      "suggested_action": "Validate the engineering capacity assumption with a concrete audit before treating this comparison as settled.",
      "linked_critique_code": "unsupported_link"
    }
  ],
  "key_assumptions": [
    "The link from Engineering Capacity to Total Cost of Ownership assumes current staffing levels are representative of what a rebuild would require.",
    "The link from Vendor Price Path to Total Cost of Ownership assumes the vendor's pricing behaviour continues along its current path.",
    "The brief frames this as a build versus extend choice, assuming no third option such as a partial migration is viable."
  ],
  "decision_quality_prompts": [
    {
      "question": "What is the base rate for efforts like Rebuild In House delivering on their original capacity estimates?",
      "principle": "Outside View (Kahneman)",
      "applies_because": "Confidence in this comparison is low, and engineering capacity is currently asserted rather than evidenced."
    },
    {
      "question": "Who will argue that Engineering Capacity matters less than the model currently treats it?",
      "principle": "Structured dissent",
      "applies_because": "A critique flagged this factor as asserted rather than evidenced, and structured dissent would test that assumption directly."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Six months in, the rebuild has stalled because Engineering Capacity fell short of what Total Cost of Ownership assumed, and costs have run past what Extend Vendor Contract would have cost.",
    "warning_signs": [
      "Engineering team reports competing priorities pulling time away from the rebuild.",
      "Early cost tracking on the rebuild exceeds the modelled trajectory."
    ],
    "mitigation": "Run the capacity audit before committing engineering resources to the rebuild.",
    "grounded_in": ["edge_capacity_tco", "fac_eng_capacity"],
    "review_trigger": "Reconvene if the capacity audit shows a shortfall against plan."
  }
}
